from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Rtpm_parse(EmssimCommand):
    def __init__(self, method='rtpm_parse', timeout=300, rpc_connection_name='localRPC'):
        super(Rtpm_parse, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Rtpm_parse, self).on_new_data(**data)

        if 'measurement' in data:
            if 'measurement_table' not in self._ret.keys():
                self._ret['measurement_table'] = []
            self._ret['measurement_table'].append(data)

        if 'rtpm_data' in data:
            if 'rtpm_data' not in self._ret.keys():
                self._ret['rtpm_data'] = []
            self._ret['rtpm_data'].append(data['rtpm_data'])

        if 'rise' in data:
            self._ret['rise'] = data['rise']

        if ('status' in data):
            self._ret['status'] = data['status']
